    h("h2", {}, `Issues (${r.issues.length})`),
    table(["Code", "Severity", "Where", "Action", "Claim"], r.issues.map((i) => [i.code, i.severity, `${i.file}:${i.line ?? ""}`, i.action, i.claim])),
